import React, { useRef, useState } from 'react';
import { useClickOutside, useHover } from '@fiverr-private/hooks';
import { Popover, PopoverAnchor, PopoverContent } from '@fiverr-private/popover';
import { Container } from '@fiverr-private/layout_components';
import { IconButton } from '@fiverr-private/button';
import { EmojiSmileyIcon } from '@fiverr-private/visuals';
import EmojiPopoverContent from './EmojiPopoverContent';
import { customEmojiPopoverClass } from './styles.ve.css';
import type { EmojiPickerProps, EmojiSelection } from './types';
import { useCustomEmojiPickerStyles } from './hooks';

export const EmojiPicker = ({
  onEmojiSelect,
  size = 'md',
  disabled = false,
  variant = 'ghost',
  position,
  disableBoxShadow = false,
  appendToBody = false,
  children,
}: EmojiPickerProps) => {
  const [isOpen, setIsOpen] = useState(false);
  const ref = useRef(null);
  const { hovered, onMouseEnter, onMouseLeave } = useHover();

  useClickOutside(ref, () => {
    if (hovered) {
      return;
    }
    setIsOpen(false);
  });

  useCustomEmojiPickerStyles(ref, isOpen);

  const toggleOpen = () => setIsOpen((prev: boolean) => !prev);

  const onPopoverEmojiSelect = (selectedEmoji: EmojiSelection) => {
    onEmojiSelect(selectedEmoji);
    setIsOpen(false);
  };

  return (
    <Popover isOpen={isOpen} position={position}>
      <PopoverAnchor disabled={disabled} onClick={toggleOpen}>
        <Container onMouseOver={onMouseEnter} onMouseLeave={onMouseLeave}>
          {children ?? (
            <IconButton aria-label="emoji" size={size} disabled={disabled} variant={variant}>
              <EmojiSmileyIcon />
            </IconButton>
          )}
        </Container>
      </PopoverAnchor>
      <PopoverContent disablePadding disableBoxShadow={disableBoxShadow} appendToBody={appendToBody}>
        <Container className={customEmojiPopoverClass} ref={ref}>
          <EmojiPopoverContent onEmojiSelect={onPopoverEmojiSelect} />
        </Container>
      </PopoverContent>
    </Popover>
  );
};

EmojiPicker.displayName = 'EmojiPicker';

export default EmojiPicker;
