import { useCallback, useEffect } from 'react';
import { theme } from '@fiverr-private/theme';

/**
 * Custom styles for the emoji picker -
 * This is a workaround that is required to match specific styles through shadow dom (not supported currently by emoji-mart).
 */

export const useCustomEmojiPickerStyles = (ref: React.RefObject<HTMLElement>, isOpen: boolean) => {
    const updateInnerPackageStyles = useCallback(() => {
        if (!ref.current) {
            return;
        }
        const root = (ref.current as HTMLElement)?.querySelector('em-emoji-picker')?.shadowRoot;
        // make sure it will not add the styles twice
        if (root?.querySelector('style#emoji-picker-custom-styles')) {
            return;
        }
        const styleText = document.createElement('style') as HTMLStyleElement;
        styleText.setAttribute('id', 'emoji-picker-custom-styles');
        styleText.textContent = `
            .menu > div:not(:first-child) { margin-top: ${theme.spacing['1']}; }
            .menu .option:hover { background-color: ${theme.colors.grey_200}; color: ${theme.colors.grey_1200}; }`;
        root?.appendChild(styleText);
    }, [ref]);

    useEffect(() => {
        if (!ref.current) {
            return;
        }
        const observer = new MutationObserver(updateInnerPackageStyles);
        observer.observe(ref.current as HTMLElement, { childList: true, subtree: true });

        return () => observer.disconnect();
    }, [ref, isOpen, updateInnerPackageStyles]);
};
