import React from 'react';
import data from '@emoji-mart/data';
import { LazyComponent } from '@fiverr-private/ui_utils';
import { Loader } from '@fiverr-private/feedback';
import { Center } from '@fiverr-private/layout_components';
import { EmptyState, EmptyStateTitle } from '@fiverr-private/data_display';
import { I18n } from '@fiverr-private/i18n-react';
import type { EmojiSelection } from './types';
import { DEFAULT_EMOJIS_COMPONENT_PROPS } from './constants';

interface EmojiPopoverContentProps {
  onEmojiSelect?: (data: EmojiSelection) => void;
}

const EmojiPopoverContent = ({ onEmojiSelect }: EmojiPopoverContentProps) => {
  const componentProps = {
    onEmojiSelect,
    data,
    ...DEFAULT_EMOJIS_COMPONENT_PROPS,
  };

  return (
    <LazyComponent
      lazyImport={() => import(/* webpackChunkName: 'EmojiMartReact' */ '@emoji-mart/react')}
      shouldImport
      componentProps={componentProps}
      placeholder={
        <Center height={435} width={316}>
          <Loader />
        </Center>
      }
      fallback={
        <Center height={435} width={316}>
          <EmptyState>
            <EmptyStateTitle>
              <I18n k="emoji_picker.fallback_message" />
            </EmptyStateTitle>
          </EmptyState>
        </Center>
      }
    />
  );
};

EmojiPopoverContent.displayName = 'EmojiPopoverContent';

export default EmojiPopoverContent;
